use desafio::mede_dois;

#[test]
fn testa_a_medida_dos_dois_emprestimos() {
    assert_eq!(mede_dois(String::from("Ana"), String::from("sol")), 6);
}

#[test]
fn testa_a_medida_do_bom_dia_e_do_x() {
    assert_eq!(mede_dois(String::from("bom dia"), String::from("x")), 8);
}
